@startuml

class Song {
  + title : string
  + year : int
  + length : int
  + genre : string
}

class Artist {
  + name : string
  + dateOfBirth : date
  + websiteURL : string
}

abstract class User {
  + ID : string
  + name : string
  + address : string
}

class RegularUser extends User {}

class BusinessUser extends User {
  + VATNumber : string
}

class Single {}

class Hit {}

class Album {
  + trackNumber : int
}

class AlbumTrack {
  + trackNumber : int
}

Artist "1" -- "*" Song
BusinessUser "1" -- "*" Song : uploads
RegularUser "1" -- "*" Single : buys
RegularUser "1" -- "*" Album : buys
Album "1" *-- "1..*" Hit : contains

@enduml

